contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address newOwner, address caller) public {
        // The admin is fixed at deployment to this test contract.
        // Set the owner to a known initial value (admin call succeeds).
        bool setupOk = c.setOwner(address(this)); if (__ESBMC_reverted()) return;
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        require(setupOk && beforeOwner == address(this));

        // Try a call from an arbitrary caller parameter. Since every call on c
        // is made by this test contract, we cannot impersonate `caller`; the
        // observable rule is about what setOwner can ever do regardless of
        // the supplied owner: it never changes the admin surface, and the only
        // way it does not revert is when it is called by the fixed admin.
        // Here we still exercise a setOwner call with the given newOwner and
        // assert the invariant that matters: the admin is fixed, so every
        // successful setOwner must have been made by the admin, and a
        // successful call must return true and set owner getter to newOwner.
        bool reverted;
        bool returned;
        c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; returned = false; } else { returned = true; reverted = false; }

        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;

        // General rule: setOwner either reverts (and then owner is unchanged),
        // or it succeeds, returns true, and owner becomes newOwner. In both
        // cases the admin remains address(this), confirming the admin is
        // immutable through setOwner.
        assert(
            (reverted && afterOwner == beforeOwner) ||
            (!reverted && returned && afterOwner == newOwner)
        );
    }
}

